import React, {useState} from 'react';
import {Alert, Box, Button, Chip, Dialog, DialogActions, DialogContent, DialogTitle, FormControlLabel, Checkbox, MenuItem, Stack, TextField, Typography} from '@mui/material';
import {Link} from 'react-router-dom';
import {useAuth} from '../../auth/AuthContext';
import {OrderDetail, Stage, UserOption, useApplyDiscountMutation, useChangeStageMutation, useOrderControlQuery, useRequestDiscountMutation, useSaveWorkMutation} from './operationsApi';
import {date, ErrorBox, localInput, money, toUtc, UserPicker} from './common';

function Editor({data,stages,users}:{data:OrderDetail;stages:Stage[];users:UserOption[]}) {
    const {isCompanyAdmin,isSuperAdmin} = useAuth(); const manager = isCompanyAdmin || isSuperAdmin;
    const [draft,setDraft] = useState({...data.work}); const [status,setStatus] = useState(data.order.statusId); const [reason,setReason] = useState('');
    const [percent,setPercent] = useState(''); const [discountReason,setDiscountReason] = useState(''); const [campaign,setCampaign] = useState(''); const [days,setDays] = useState(7);
    const [save,saveState] = useSaveWorkMutation(); const [change,changeState] = useChangeStageMutation(); const [request,requestState] = useRequestDiscountMutation(); const [apply,applyState] = useApplyDiscountMutation();
    const [success,setSuccess] = useState('');
    const busy = saveState.isLoading || changeState.isLoading || requestState.isLoading || applyState.isLoading;
    const run = async (action:()=>Promise<unknown>,message:string) => {setSuccess(''); try {await action(); setSuccess(message);} catch { /* ErrorBox renders the server result. */ }};
    return <Stack spacing={2}>
        <Typography variant="h6">{data.order.customerName} · {data.order.phone}</Typography>
        <Typography>Сумма: {money(data.order.finalSum)} · Скидка: {data.order.discount}% · Оплачено: {money(data.work.paidAmount)}</Typography>
        <Button component={Link} to={`/ordersManagement/${data.order.id}`}>Открыть карточку заказа</Button>
        <ErrorBox error={saveState.error || changeState.error || requestState.error || applyState.error}/>{success && <Alert severity="success">{success}</Alert>}
        <Typography variant="h6">Этап воронки</Typography>
        <TextField select label="Статус" value={status} onChange={e=>setStatus(Number(e.target.value))}>{stages.map(s=><MenuItem key={s.status.id} value={s.status.id}>{s.status.name}</MenuItem>)}</TextField>
        <TextField label="Причина изменения / возврата / отмены" value={reason} onChange={e=>setReason(e.target.value)} inputProps={{maxLength:1000}}/>
        <Button disabled={busy || status===data.order.statusId} variant="contained" onClick={()=>void run(()=>change({orderId:data.order.id,statusId:status,version:data.order.version,reason}).unwrap(),'Статус обновлён')}>Перевести на этап</Button>
        <Typography variant="h6">Контроль исполнения</Typography>
        <TextField type="datetime-local" label="Ожидаемое завершение" InputLabelProps={{shrink:true}} value={localInput(draft.expectedCloseAt)} onChange={e=>setDraft({...draft,expectedCloseAt:toUtc(e.target.value)})}/>
        <TextField label="Следующее действие" multiline value={draft.nextAction} onChange={e=>setDraft({...draft,nextAction:e.target.value})} inputProps={{maxLength:1000}}/>
        <TextField type="datetime-local" label="Срок следующего контакта" InputLabelProps={{shrink:true}} value={localInput(draft.nextActionAt)} onChange={e=>setDraft({...draft,nextActionAt:toUtc(e.target.value)})}/>
        <TextField select label="Приоритет" value={draft.priority} onChange={e=>setDraft({...draft,priority:e.target.value})}>{[['low','Низкий'],['normal','Обычный'],['high','Высокий']].map(([id,label])=><MenuItem key={id} value={id}>{label}</MenuItem>)}</TextField>
        <TextField type="number" label="Оплачено" disabled={!manager} value={draft.paidAmount} onChange={e=>setDraft({...draft,paidAmount:Number(e.target.value)})} inputProps={{min:0,max:data.order.finalSum,step:0.01}} helperText="Изменение учтённой оплаты доступно руководителю."/>
        <UserPicker label="Подписчики изменений заказа" users={users} ids={draft.watcherUserIds} onChange={ids=>setDraft({...draft,watcherUserIds:ids})}/>
        <Typography color="text.secondary">Ответственные и сотрудники этапа получают уведомления автоматически.</Typography>
        <FormControlLabel label="Также уведомлять через Telegram" control={<Checkbox checked={draft.notifyTelegram} onChange={e=>setDraft({...draft,notifyTelegram:e.target.checked})}/>}/>
        <Button variant="contained" disabled={busy} onClick={()=>void run(()=>save({orderId:data.order.id,work:draft}).unwrap(),'Контроль заказа сохранён')}>Сохранить контроль</Button>
        <Typography variant="h6">Индивидуальная скидка</Typography>
        <Stack direction={{xs:'column',sm:'row'}} spacing={1}><TextField type="number" label="Скидка, %" value={percent} onChange={e=>setPercent(e.target.value)} inputProps={{min:0,max:100,step:0.01}}/><TextField type="number" label="Срок, дней" value={days} onChange={e=>setDays(Number(e.target.value))} inputProps={{min:1,max:90}}/></Stack>
        <TextField label="Причина скидки" value={discountReason} onChange={e=>setDiscountReason(e.target.value)} inputProps={{maxLength:1000}}/>
        <TextField label="Кампания / персональные условия" value={campaign} onChange={e=>setCampaign(e.target.value)} inputProps={{maxLength:100}}/>
        <Button disabled={busy || !discountReason.trim() || Number(percent)<=0} onClick={()=>void run(()=>request({orderId:data.order.id,percent:Number(percent),reason:discountReason,campaign,validDays:days}).unwrap(),'Заявка отправлена руководителям')}>Запросить согласование</Button>
        {data.discounts.map(d=><Box key={d.id} sx={{p:2,border:'1px solid',borderColor:'divider',borderRadius:2}}><Chip label={{pending:'На согласовании',approved:'Согласована',rejected:'Отклонена'}[d.state] || d.state}/><Typography>{d.percent}% · {d.reason} · {d.campaign}</Typography><Typography variant="caption">До {date(d.expiresAt)}. {d.decisionNote}</Typography>{d.state==='approved' && new Date(d.expiresAt)>new Date() && <Button disabled={busy || data.order.discount===d.percent} onClick={()=>void run(()=>apply({id:d.id,orderVersion:data.order.version}).unwrap(),'Скидка применена к заказу')}>Применить скидку</Button>}</Box>)}
        <Typography variant="h6">История изменений</Typography>
        {data.history.length===0 && <Typography color="text.secondary">Новые изменения появятся в истории после сохранения.</Typography>}
        {data.history.map(h=><Box key={h.id} sx={{borderLeft:'3px solid',borderColor:'primary.main',pl:2}}><Typography variant="caption">{date(h.createdAt)} · {users.find(u=>u.id===h.actorUserId)?.name || (h.actorUserId ? `Пользователь №${h.actorUserId}` : 'Система')}</Typography><Typography sx={{whiteSpace:'pre-wrap',overflowWrap:'anywhere'}}>{h.detail}</Typography></Box>)}
        {data.calls.length>0 && <><Typography variant="h6">Звонки по заказу</Typography>{data.calls.map(c=><Button key={c.id} component={Link} to={`/telephony?call=${c.id}`}>+{c.phone} · {date(c.startedAt)}</Button>)}</>}
    </Stack>;
}
export default function OrderControlDialog({id,stages,users,onClose}:{id:number|null;stages:Stage[];users:UserOption[];onClose:()=>void}) {
    const detail = useOrderControlQuery(id || 0,{skip:!id,pollingInterval:5000});
    return <Dialog open={!!id} onClose={onClose} fullWidth maxWidth="md"><DialogTitle>Контроль заказа №{id}</DialogTitle><DialogContent dividers>{detail.isLoading && <Typography>Загрузка…</Typography>}<ErrorBox error={detail.error} retry={()=>void detail.refetch()}/>{detail.data && <Editor key={`${id}-${detail.data.work.version}-${detail.data.order.version}`} data={detail.data} stages={stages} users={users}/>}</DialogContent><DialogActions><Button onClick={onClose}>Закрыть</Button></DialogActions></Dialog>;
}
