import React from 'react';
import {Alert, Autocomplete, Button, TextField} from '@mui/material';
import {getApiErrorMessage} from '../../api/errors';
import {UserOption} from './operationsApi';
export const money = (value:number) => new Intl.NumberFormat('ru-BY',{maximumFractionDigits:2,minimumFractionDigits:2}).format(value);
export const date = (value:string|null) => value ? new Date(value).toLocaleString('ru-BY') : '—';
export const localInput = (value:string|null) => {
    if (!value) return '';
    const dt = new Date(value); return new Date(dt.getTime() - dt.getTimezoneOffset()*60000).toISOString().slice(0,16);
};
export const toUtc = (value:string) => value ? new Date(value).toISOString() : null;
export const ErrorBox = ({error,retry}:{error:unknown;retry?:()=>void}) => error ? <Alert severity="error">{getApiErrorMessage(error,'Не удалось выполнить операцию.')} {retry && <Button onClick={retry}>Обновить</Button>}</Alert> : null;
export const UserPicker = ({users,ids,onChange,label}:{users:UserOption[];ids:number[];onChange:(ids:number[])=>void;label:string}) => <Autocomplete multiple options={users} value={users.filter(u => ids.includes(u.id))} isOptionEqualToValue={(a,b)=>a.id===b.id} getOptionLabel={u=>u.name} onChange={(_,value)=>onChange(value.map(u=>u.id))} renderInput={params=><TextField {...params} label={label}/>}/>;
