import React, {useState} from 'react';
import {Alert, Box, Button, Card, CardContent, Checkbox, Chip, Dialog, DialogActions, DialogContent, DialogTitle, FormControlLabel, MenuItem, Stack, Tab, Tabs, Table, TableBody, TableCell, TableHead, TableRow, TextField, Typography} from '@mui/material';
import {Link, useSearchParams} from 'react-router-dom';
import {useAuth} from '../../auth/AuthContext';
import {MainDiv, PageHeader, PageTitle, Surface} from '../../ui/commonStyled/commonStyled';
import {StageRule, Discount, Policy, useDecideDiscountMutation, useDiscountPolicyQuery, useDiscountsQuery, useInboxQuery, useMetricsQuery, useOperationsUsersQuery, usePipelineQuery, useReadNotificationMutation, useSaveDiscountPolicyMutation, useSaveStageMutation} from './operationsApi';
import {date, ErrorBox, money, UserPicker} from './common';
import OrderControlDialog from './OrderControlDialog';

export default function OrderPipelinePage() {
    const {user,isCompanyAdmin,isSuperAdmin} = useAuth(); const manager = isCompanyAdmin || isSuperAdmin;
    const [params,setParams] = useSearchParams(); const selected = Number(params.get('order')) || null;
    const [tab,setTab] = useState(0); const [query,setQuery] = useState(''); const [responsible,setResponsible] = useState(''); const [overdue,setOverdue] = useState(false); const [mine,setMine] = useState(false);
    const pipeline = usePipelineQuery({query,responsible:responsible?Number(responsible):undefined,overdueOnly:overdue,mine},{pollingInterval:10000});
    const users = useOperationsUsersQuery(); const metrics = useMetricsQuery(undefined,{skip:tab!==1,pollingInterval:15000}); const discounts = useDiscountsQuery(undefined,{skip:tab!==2,pollingInterval:10000});
    const inbox = useInboxQuery(undefined,{pollingInterval:5000}); const policy = useDiscountPolicyQuery();
    const [read,readState] = useReadNotificationMutation(); const [saveStage,stageState] = useSaveStageMutation(); const [savePolicy,policyState] = useSaveDiscountPolicyMutation(); const [decide,decideState] = useDecideDiscountMutation();
    const [editing,setEditing] = useState<StageRule|null>(null); const [policyDraft,setPolicyDraft] = useState<Policy|null>(null); const [decision,setDecision] = useState<{discount:Discount;approve:boolean}|null>(null); const [note,setNote] = useState('');
    const open = (id:number)=>setParams({order:String(id)}); const unread = inbox.data?.filter(x=>!x.readAt).length || 0;
    const commit = async (action:()=>Promise<unknown>,close:()=>void)=>{try{await action();close();}catch{/* Mutation error is rendered. */}};
    const employeeName = (ids:number[]) => ids.map(id=>users.data?.find(u=>u.id===id)?.name || `№${id}`).join(', ');
    return <MainDiv><PageHeader><PageTitle>Воронка и контроль продаж</PageTitle><Button component={Link} to="/telephony">Телефония</Button><Button component={Link} to="/ordersManagement/createOrder">Новый заказ</Button></PageHeader>
        <Tabs value={tab} onChange={(_,v)=>setTab(v)} variant="scrollable" allowScrollButtonsMobile><Tab label="Воронка"/><Tab label="Продажи и сотрудники"/><Tab label="Согласование скидок"/><Tab label={`Уведомления (${unread})`}/>{manager && <Tab label="Правила воронки"/>}</Tabs>
        <Box sx={{mt:2}}><ErrorBox error={users.error || pipeline.error} retry={()=>void pipeline.refetch()}/></Box>
        {tab===0 && <Stack spacing={2} sx={{mt:2}}><Stack direction={{xs:'column',md:'row'}} spacing={2}><TextField label="Поиск заказа, клиента или номера" value={query} onChange={e=>setQuery(e.target.value)}/><TextField select label="Ответственный" value={responsible} onChange={e=>setResponsible(e.target.value)} sx={{minWidth:220}}><MenuItem value="">Все сотрудники</MenuItem>{users.data?.map(u=><MenuItem key={u.id} value={u.id}>{u.name}</MenuItem>)}</TextField><FormControlLabel label="Только мои" control={<Checkbox checked={mine} onChange={e=>setMine(e.target.checked)}/>}/><FormControlLabel label="Только просроченные" control={<Checkbox checked={overdue} onChange={e=>setOverdue(e.target.checked)}/>}/></Stack>
            {pipeline.isLoading && <Typography>Загрузка воронки…</Typography>}{pipeline.data?.truncated && <Alert severity="info">Показаны первые {pipeline.data.orders.length} из {pipeline.data.totalCount} найденных заказов в пределах последних 5000 записей. Уточните поиск или ответственного.</Alert>}
            {pipeline.data?.orders.length===0 && <Alert severity="info">Заказы по этим условиям не найдены.</Alert>}
            <Box sx={{display:'flex',gap:2,overflowX:'auto',pb:2,alignItems:'flex-start'}}>{pipeline.data?.stages.map(stage=>{
                const cards = pipeline.data?.orders.filter(c=>c.order.statusId===stage.status.id) || [];
                return <Box key={stage.status.id} sx={{minWidth:280,width:300,flexShrink:0,p:1.5,bgcolor:'action.hover',borderRadius:3}}><Stack spacing={1}><Typography variant="h6">{stage.status.name} <Chip size="small" label={cards.length}/></Typography><Typography variant="caption">{money(cards.reduce((sum,c)=>sum+c.order.finalSum,0))} · {stage.rule.isClosed?'Закрытый этап':`Срок ${stage.rule.maxHours} ч · ${stage.rule.probability}%`}</Typography>{cards.map(c=><Card key={c.order.id} variant="outlined"><CardContent><Stack spacing={1}><Button sx={{justifyContent:'flex-start'}} onClick={()=>open(c.order.id)}>№{c.order.id} · {c.order.customerName}</Button><Typography>{money(c.order.finalSum)}</Typography><Typography variant="body2">{employeeName(c.order.responsibleUserIds) || 'Ответственный не назначен'}</Typography><Typography variant="caption">На этапе с {date(c.work.stageEnteredAt)}</Typography>{c.work.nextAction && <Typography variant="body2">{c.work.nextAction} · {date(c.work.nextActionAt)}</Typography>}<Stack direction="row" spacing={1} flexWrap="wrap">{c.overdue && <Chip size="small" color="error" label="Просрочен этап"/>}{c.contactOverdue && <Chip size="small" color="warning" label="Просрочен контакт"/>}{c.work.priority==='high' && <Chip size="small" color="secondary" label="Высокий приоритет"/>}</Stack></Stack></CardContent></Card>)}</Stack></Box>;
            })}</Box></Stack>}
        {tab===1 && <Surface><ErrorBox error={metrics.error} retry={()=>void metrics.refetch()}/>{metrics.data && <Stack spacing={2}>{metrics.data.truncated && <Alert severity="warning">Отчёт ограничен последними 5000 заказами и звонками.</Alert>}<Box sx={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(180px,1fr))',gap:2}}>{[['Активные заказы',metrics.data.activeOrders],['Сумма воронки',money(metrics.data.pipelineAmount)],['Взвешенный прогноз',money(metrics.data.weightedAmount)],['Завершённые продажи',money(metrics.data.wonAmount)],['Просрочки',metrics.data.overdueOrders],['Без ответственного',metrics.data.unassignedOrders],['Скидки на согласовании',metrics.data.pendingDiscounts],['Просроченные перезвоны',metrics.data.callbackOverdue]].map(([label,value])=><Card key={label}><CardContent><Typography color="text.secondary">{label}</Typography><Typography variant="h5">{value}</Typography></CardContent></Card>)}</Box><Typography variant="h6">Работа сотрудников</Typography><Typography color="text.secondary">Заказ с несколькими ответственными учитывается у каждого. Суммы сотрудников не складываются в общую выручку. Показатели отражают текущее состояние заказов; завершённая сумма не означает поступление оплаты.</Typography><Box sx={{overflowX:'auto'}}><Table size="small"><TableHead><TableRow>{['Сотрудник','В работе','Завершено','Сумма','Просрочки','Звонки','Перезвоны'].map(h=><TableCell key={h}>{h}</TableCell>)}</TableRow></TableHead><TableBody>{metrics.data.employees.map(u=><TableRow key={u.id}><TableCell>{u.name}</TableCell><TableCell>{u.activeOrders}</TableCell><TableCell>{u.wonOrders}</TableCell><TableCell>{money(u.wonAmount)}</TableCell><TableCell>{u.overdueOrders}</TableCell><TableCell>{u.assignedCalls}</TableCell><TableCell>{u.callbackOverdue}</TableCell></TableRow>)}</TableBody></Table></Box></Stack>}</Surface>}
        {tab===2 && <Surface><ErrorBox error={discounts.error} retry={()=>void discounts.refetch()}/><Typography color="text.secondary">Сотрудник: до {policy.data?.employeeLimitPercent ?? '…'}%. Максимальная скидка компании: {policy.data?.maximumPercent ?? '…'}%. Согласование привязано к сумме заказа и сроку.</Typography><Stack spacing={2} sx={{mt:2}}>{discounts.data?.length===0 && <Typography>Заявок на скидки пока нет.</Typography>}{discounts.data?.map(d=><Card key={d.id} variant="outlined"><CardContent><Stack spacing={1}><Button onClick={()=>open(d.orderId)}>Заказ №{d.orderId} · {d.percent}%</Button><Typography>{d.reason} · {d.campaign}</Typography><Typography variant="caption">{employeeName([d.requestedBy])} · до {date(d.expiresAt)} · {d.state==='pending'?'На согласовании':d.state==='approved'?'Согласована':'Отклонена'}</Typography>{d.decisionNote && <Typography>{d.decisionNote}</Typography>}{manager && d.state==='pending' && d.requestedBy!==user?.id && <Stack direction="row" spacing={1}><Button disabled={new Date(d.expiresAt)<=new Date()} onClick={()=>{setDecision({discount:d,approve:true});setNote('');}}>Согласовать</Button><Button disabled={new Date(d.expiresAt)<=new Date()} color="error" onClick={()=>{setDecision({discount:d,approve:false});setNote('');}}>Отклонить</Button></Stack>}{d.requestedBy===user?.id && d.state==='pending' && <Typography variant="caption">Свою заявку согласует другой руководитель.</Typography>}</Stack></CardContent></Card>)}</Stack></Surface>}
        {tab===3 && <Surface><ErrorBox error={inbox.error || readState.error} retry={()=>void inbox.refetch()}/><Stack spacing={2}>{inbox.data?.length===0 && <Typography>Уведомлений пока нет.</Typography>}{inbox.data?.map(n=><Alert key={n.id} severity={n.readAt?'info':'warning'} action={<Stack>{n.orderId && <Button onClick={()=>open(n.orderId!)}>Заказ</Button>}{!n.readAt && <Button disabled={readState.isLoading} onClick={()=>void read(n.id)}>Прочитано</Button>}</Stack>}><Typography sx={{whiteSpace:'pre-wrap',overflowWrap:'anywhere'}}>{n.body}</Typography><Typography variant="caption">{date(n.createdAt)}{n.telegramQueuedAt?' · Telegram поставлен в очередь':''}</Typography>{n.deliveryError && <Typography variant="caption" display="block">Telegram: {n.deliveryError} Уведомление сохранено в CRM.</Typography>}</Alert>)}</Stack></Surface>}
        {tab===4 && manager && <Surface><Stack spacing={2}><Typography variant="h6">Правила переходов и уведомлений</Typography><Typography color="text.secondary">Пустой список разрешённых переходов разрешает любой этап. Отмена, возврат назад и повторное открытие требуют причину. Названия статусов меняются в справочниках CRM.</Typography>{pipeline.data?.stages.map(s=><Stack key={s.status.id} direction="row" justifyContent="space-between"><Typography>{s.status.name} · {s.rule.maxHours} ч · {s.rule.probability}%</Typography><Button onClick={()=>setEditing({...s.rule})}>Настроить</Button></Stack>)}<Typography variant="h6">Лимиты скидок</Typography><ErrorBox error={policy.error}/>{policy.data && <Button onClick={()=>setPolicyDraft({...policy.data!})}>Лимит сотрудника {policy.data.employeeLimitPercent}% · максимум {policy.data.maximumPercent}%</Button>}</Stack></Surface>}
        <OrderControlDialog id={selected} stages={pipeline.data?.stages || []} users={users.data || []} onClose={()=>setParams({})}/>
        <Dialog open={!!editing} onClose={()=>setEditing(null)} fullWidth><DialogTitle>Правила этапа</DialogTitle><DialogContent><Stack spacing={2} sx={{pt:1}}><ErrorBox error={stageState.error}/>{editing && <><TextField type="number" label="Порядок этапа" value={editing.position} onChange={e=>setEditing({...editing,position:Number(e.target.value)})}/><TextField type="number" label="Вероятность продажи, %" value={editing.probability} onChange={e=>setEditing({...editing,probability:Number(e.target.value)})}/><TextField type="number" label="Максимум часов на этапе" value={editing.maxHours} onChange={e=>setEditing({...editing,maxHours:Number(e.target.value)})}/>{(['isClosed','isWon','requirePayment'] as const).map((key,i)=><FormControlLabel key={key} label={['Закрытый этап','Успешная продажа','Требовать полную оплату'][i]} control={<Checkbox checked={editing[key]} onChange={e=>setEditing({...editing,[key]:e.target.checked})}/>}/>)}<TextField select SelectProps={{multiple:true}} label="Разрешённые следующие этапы" value={editing.allowedNextStatusIds} onChange={e=>setEditing({...editing,allowedNextStatusIds:e.target.value as unknown as number[]})}>{pipeline.data?.stages.map(s=><MenuItem key={s.status.id} value={s.status.id}>{s.status.name}</MenuItem>)}</TextField><UserPicker users={users.data || []} ids={editing.notifyUserIds} label="Дополнительно уведомлять на этом этапе" onChange={ids=>setEditing({...editing,notifyUserIds:ids})}/></>}</Stack></DialogContent><DialogActions><Button onClick={()=>setEditing(null)}>Отмена</Button><Button disabled={stageState.isLoading} onClick={()=>editing && void commit(()=>saveStage(editing).unwrap(),()=>setEditing(null))}>Сохранить</Button></DialogActions></Dialog>
        <Dialog open={!!policyDraft} onClose={()=>setPolicyDraft(null)}><DialogTitle>Лимиты скидок</DialogTitle><DialogContent><Stack spacing={2} sx={{pt:1}}><ErrorBox error={policyState.error}/>{policyDraft && <><TextField type="number" label="Лимит сотрудника, %" value={policyDraft.employeeLimitPercent} onChange={e=>setPolicyDraft({...policyDraft,employeeLimitPercent:Number(e.target.value)})}/><TextField type="number" label="Максимальная скидка, %" value={policyDraft.maximumPercent} onChange={e=>setPolicyDraft({...policyDraft,maximumPercent:Number(e.target.value)})}/></>}</Stack></DialogContent><DialogActions><Button onClick={()=>setPolicyDraft(null)}>Отмена</Button><Button disabled={policyState.isLoading} onClick={()=>policyDraft && void commit(()=>savePolicy(policyDraft).unwrap(),()=>setPolicyDraft(null))}>Сохранить</Button></DialogActions></Dialog>
        <Dialog open={!!decision} onClose={()=>setDecision(null)}><DialogTitle>{decision?.approve?'Согласовать':'Отклонить'} скидку</DialogTitle><DialogContent><ErrorBox error={decideState.error}/><TextField fullWidth label="Комментарий решения" value={note} onChange={e=>setNote(e.target.value)} sx={{mt:1}} inputProps={{maxLength:1000}}/></DialogContent><DialogActions><Button onClick={()=>setDecision(null)}>Отмена</Button><Button disabled={decideState.isLoading || !note.trim()} onClick={()=>decision && void commit(()=>decide({id:decision.discount.id,approve:decision.approve,note,version:decision.discount.version}).unwrap(),()=>setDecision(null))}>Подтвердить</Button></DialogActions></Dialog>
    </MainDiv>;
}
